def proof_cost(n: int, temperature: float = 300.0, alphabet_size: int = 2) -> float:
    import math
    k_B = 1.380649e-23
    return n * k_B * temperature * math.log(alphabet_size)

def landauer_capacity(energy: float, temp: float = 300.0, b: int = 2) -> tuple:
    import math
    k_B = 1.380649e-23
    max_len = int(energy / (k_B * temp * math.log(b)))
    return (max_len, 2 * b ** max_len)

def search_gap(b: int, n: int, k: int) -> tuple:
    gap = n - k - 1
    return (gap, b ** gap)
